import { buttonClasses } from "@mui/material/Button";
import { chipClasses } from "@mui/material/Chip";
import { outlinedInputClasses } from "@mui/material/OutlinedInput";
import {
  createTheme,
  type Shadows,
  type Theme,
  type ThemeOptions,
} from "@mui/material/styles";
import { safeAreaInset } from "./safe-area";
import { SHELL_DARK, SHELL_LIGHT } from "./theme-colors";

declare module "@mui/material/styles" {
  interface CssThemeVariables {
    enabled: true;
  }

  interface Shape {
    borderRadiusSm: string;
    borderRadiusLg: string;
    borderRadiusFull: string;
  }

  interface ShapeOptions {
    borderRadiusSm?: string;
    borderRadiusLg?: string;
    borderRadiusFull?: string;
  }
}

const grey = {
  50: "#f8faff",
  100: "#f3f5fa",
  200: "#eceef3",
  300: "#dde0e6",
  400: "#babdc3",
  500: "#9b9ea4",
  600: "#72757b",
  700: "#5e6167",
  800: "#3f4248",
  900: "#1e2127",
  A100: "#f3f5fa",
  A200: "#eceef3",
  A400: "#babdc3",
  A700: "#5e6167",
};

const shadows = [
  "none",
  ...Array.from({ length: 24 }, (_, index) => softShadow(index + 1)),
] as Shadows;

function softShadow(elevation: number) {
  const ring = "0 0 0 1px rgb(16 24 40 / 0.05)";
  const key = `0 ${Math.ceil(elevation / 2)}px ${elevation + 1}px rgb(16 24 40 / 0.06)`;
  const ambientAlpha = (0.1 + elevation * 0.003).toFixed(3);
  const ambient = `0 ${2 * elevation}px ${4 * elevation}px -${1.5 * elevation}px rgb(16 24 40 / ${ambientAlpha})`;

  return `${ring}, ${key}, ${ambient}`;
}

// Theme overrides follow MUI's state rules, so the sticky touch hover would
// otherwise repaint the focused, error, and disabled outlines.
const idleTouchHoverOutline = `&:hover:not(.${outlinedInputClasses.focused}, .${outlinedInputClasses.error}, .${outlinedInputClasses.disabled}) .${outlinedInputClasses.notchedOutline}`;

function buttonFeedbackTiming(theme: Theme) {
  return {
    transitionDuration: `${theme.transitions.duration.shortest}ms`,
    transitionTimingFunction: theme.transitions.easing.easeOut,
    "&:active": {
      transitionDuration: "0ms",
    },
  };
}

const themeOptions = {
  focusVisible: true,
  shadows,
  // Strings so radii returned from sx callbacks pass through as lengths; a
  // number would be multiplied by the base again. MUI's Paper-based surfaces
  // (menus, popovers, alerts, snackbars) and tooltips inherit the base.
  shape: {
    borderRadius: "20px",
    borderRadiusSm: "12px",
    borderRadiusLg: "32px",
    borderRadiusFull: "9999px",
  },
  cssVariables: {
    colorSchemeSelector: "class",
    // index.html owns color-scheme; MUI only emits the palette vars.
    disableCssColorScheme: true,
  },
  colorSchemes: {
    light: {
      palette: {
        primary: { main: "#0b7468" },
        grey,
        background: { default: SHELL_LIGHT, paper: "#ffffff" },
        Button: {
          inheritContainedBg: "#ffffff",
          inheritContainedHoverBg: grey[100],
        },
        Chip: { defaultBorder: "rgba(0, 0, 0, 0.5)" },
        action: { active: "rgba(0, 0, 0, 0.6)" },
      },
    },
    dark: {
      palette: {
        primary: { main: "#3fd0bd" },
        grey,
        background: { default: SHELL_DARK, paper: "#1a1d23" },
        error: { main: "#f2b8b5" },
        Chip: { defaultBorder: "rgba(255, 255, 255, 0.42)" },
        action: { active: "rgba(255, 255, 255, 0.7)" },
      },
    },
  },
  motion: {
    reducedMotion: "system",
  },
  typography: {
    fontFamily: "system-ui, sans-serif",
    fontWeightLight: 400,
    fontWeightBold: 600,
    h6: {
      fontWeight: 600,
    },
    button: {
      textTransform: "none",
    },
  },
  components: {
    MuiCssBaseline: {
      styleOverrides: {
        html: {
          overscrollBehaviorY: "none",
        },
        body: {
          userSelect: "none",
        },
      },
    },
    MuiAppBar: {
      defaultProps: {
        color: "transparent",
        elevation: 0,
      },
      styleOverrides: {
        root: ({ theme }) => ({
          borderBottom: `1px solid ${theme.vars.palette.divider}`,
        }),
      },
    },
    MuiToolbar: {
      styleOverrides: {
        gutters: ({ theme }) => ({
          paddingLeft: theme.spacing(3),
          paddingRight: theme.spacing(3),
        }),
      },
    },
    MuiDrawer: {
      styleOverrides: {
        paper: ({ theme }) => {
          const radius = theme.vars.shape.borderRadius;

          return {
            backgroundColor: theme.vars.palette.background.default,
            backgroundImage: "none",
            // Physical corners, like the drawer's own `left`/`right` offset, are
            // mirrored by the RTL stylis plugin, so the inner edge stays rounded.
            variants: [
              {
                props: { anchor: "left" },
                style: {
                  borderTopRightRadius: radius,
                  borderBottomRightRadius: radius,
                  paddingLeft: safeAreaInset("left"),
                },
              },
              {
                props: { anchor: "right" },
                style: {
                  borderTopLeftRadius: radius,
                  borderBottomLeftRadius: radius,
                  paddingRight: safeAreaInset("right"),
                },
              },
            ],
          };
        },
      },
    },
    MuiDialog: {
      styleOverrides: {
        paper: ({ theme }) => ({
          variants: [
            {
              props: { fullScreen: false },
              style: {
                borderRadius: theme.vars.shape.borderRadiusLg,
              },
            },
            {
              props: { fullScreen: true },
              style: {
                paddingTop: safeAreaInset("top"),
                paddingRight: safeAreaInset("right"),
                paddingBottom: safeAreaInset("bottom"),
                paddingLeft: safeAreaInset("left"),
              },
            },
          ],
        }),
      },
    },
    MuiDialogActions: {
      styleOverrides: {
        root: {
          padding: 16,
        },
      },
    },
    MuiButtonBase: {
      defaultProps: {
        disableRipple: true,
      },
      styleOverrides: {
        root: ({ theme }) => ({
          "&::before": {
            content: '""',
            position: "absolute",
            inset: 0,
            borderRadius: "inherit",
            backgroundColor: "currentColor",
            opacity: 0,
            pointerEvents: "none",
            transition: theme.transitions.create("opacity", {
              duration: theme.transitions.duration.shortest,
              easing: theme.transitions.easing.easeOut,
            }),
            "@media (prefers-reduced-motion: reduce)": {
              transition: "none",
            },
          },
          "&:active::before": {
            opacity: theme.vars.palette.action.activatedOpacity,
            transitionDuration: "0ms",
          },
        }),
      },
    },
    MuiButton: {
      styleOverrides: {
        root: ({ theme }) => ({
          borderRadius: theme.vars.shape.borderRadiusFull,
          paddingTop: 12,
          paddingBottom: 12,
          ...buttonFeedbackTiming(theme),
          variants: [
            {
              props: { variant: "contained", color: "inherit" },
              style: theme.applyStyles("light", {
                [`&.${buttonClasses.disabled}`]: {
                  backgroundColor: "transparent",
                },
              }),
            },
          ],
        }),
      },
    },
    MuiIconButton: {
      styleOverrides: {
        root: ({ theme }) => buttonFeedbackTiming(theme),
      },
    },
    MuiFab: {
      styleOverrides: {
        root: ({ theme }) => buttonFeedbackTiming(theme),
      },
    },
    MuiOutlinedInput: {
      styleOverrides: {
        root: ({ theme }) => ({
          borderRadius: theme.vars.shape.borderRadiusFull,
          "@media (hover: none)": {
            [idleTouchHoverOutline]: {
              borderColor: theme.vars.palette.Chip.defaultBorder,
            },
          },
          variants: [
            {
              props: { multiline: true },
              style: { borderRadius: theme.vars.shape.borderRadius },
            },
          ],
        }),
        notchedOutline: ({ theme }) => ({
          borderColor: theme.vars.palette.Chip.defaultBorder,
        }),
      },
    },
    MuiChip: {
      styleOverrides: {
        clickable: ({ theme }) => ({
          ...theme.typography.body2,
          height: 40,
          borderRadius: theme.vars.shape.borderRadiusFull,
          ...buttonFeedbackTiming(theme),
          [`& .${chipClasses.label}`]: {
            paddingLeft: 15,
            paddingRight: 15,
          },
          [`& .${chipClasses.icon}`]: {
            marginLeft: 12,
          },
        }),
      },
    },
    MuiListItemButton: {
      styleOverrides: {
        root: ({ theme }) => ({
          borderRadius: theme.vars.shape.borderRadiusFull,
          ...buttonFeedbackTiming(theme),
        }),
      },
    },
    MuiMenuItem: {
      styleOverrides: {
        root: ({ theme }) => ({
          marginInline: 4,
          borderRadius: theme.vars.shape.borderRadiusSm,
        }),
      },
    },
    MuiAutocomplete: {
      defaultProps: {
        slotProps: {
          popper: {
            modifiers: [{ name: "offset", options: { offset: [0, 4] } }],
          },
        },
      },
      styleOverrides: {
        option: ({ theme }) => ({
          marginInline: 4,
          borderRadius: theme.vars.shape.borderRadiusSm,
        }),
      },
    },
    MuiSlider: {
      styleOverrides: {
        root: {
          variants: [
            {
              props: { orientation: "horizontal" },
              style: {
                padding: "12px 0",
                "@media (pointer: coarse)": { padding: "12px 0" },
              },
            },
          ],
        },
        mark: {
          width: 2,
          height: 12,
          borderRadius: 1,
        },
        markActive: ({ theme }) => ({
          backgroundColor: theme.vars.palette.background.default,
        }),
      },
    },
    MuiTooltip: {
      defaultProps: {
        enterDelay: 500,
      },
      styleOverrides: {
        tooltip: ({ theme }) => ({
          fontSize: theme.typography.pxToRem(13),
        }),
      },
    },
  },
} satisfies ThemeOptions;

export const ltrTheme = createTheme({
  ...themeOptions,
  direction: "ltr",
});

export const rtlTheme = createTheme({
  ...themeOptions,
  direction: "rtl",
});
