import LibraryAddOutlinedIcon from "@mui/icons-material/LibraryAddOutlined";
import Box from "@mui/material/Box";
import Button from "@mui/material/Button";
import List from "@mui/material/List";
import ListItem from "@mui/material/ListItem";
import ListItemButton from "@mui/material/ListItemButton";
import ListItemIcon from "@mui/material/ListItemIcon";
import ListItemText from "@mui/material/ListItemText";
import { m } from "@paraglide/messages.js";
import { usePerfSpan } from "@perf";
import { useTranslate } from "@shared/language/use-translate";
import { useSnackbar } from "@shared/snackbar/use-snackbar";
import { EmptyState } from "@shared/ui/empty-state";
import { ErrorState } from "@shared/ui/error-state";
import { LoadingState } from "@shared/ui/loading-state";
import { useState } from "react";
import { useImportBoardFiles } from "../import/use-import-board-files";
import type { BoardSetRecord } from "../storage/board-set-storage";
import { BoardSetDeleteDialog } from "./board-set-delete-dialog";
import { BoardSetDetailsDialog } from "./board-set-details-dialog";
import { BoardSetList } from "./board-set-list";
import { deleteBoardSet } from "./board-sets-store";
import { useBoardSets } from "./use-board-sets";

interface BoardSetLibraryProps {
  activeBoardSetId?: string;
  onNavigate: () => void;
}

export function BoardSetLibrary({
  activeBoardSetId,
  onNavigate,
}: BoardSetLibraryProps) {
  const t = useTranslate();
  const { boardSets, isLoading, error } = useBoardSets();
  const { pickAndImport } = useImportBoardFiles();
  const { showSnackbar } = useSnackbar();

  usePerfSpan("flow:library:import", boardSets);

  const [deleteTarget, setDeleteTarget] = useState<BoardSetRecord | null>(null);
  const [detailsTarget, setDetailsTarget] = useState<BoardSetRecord | null>(
    null,
  );

  async function handleDelete() {
    if (!deleteTarget) {
      return;
    }

    const { id, name } = deleteTarget;
    setDeleteTarget(null);

    try {
      await deleteBoardSet(id);
    } catch {
      showSnackbar({
        message: (t) => t(m.libraryDeleteFailed, { name }),
        severity: "error",
      });
    }
  }

  if (isLoading) {
    return (
      <Box sx={{ height: "100%", px: 2 }}>
        <LoadingState message={t(m.libraryLoading)} />
      </Box>
    );
  }

  if (error && boardSets.length === 0) {
    return (
      <Box sx={{ height: "100%", px: 2 }}>
        <ErrorState icon={null} title={t(m.libraryLoadFailed)} />
      </Box>
    );
  }

  if (boardSets.length === 0) {
    return (
      <Box sx={{ height: "100%", px: 2 }}>
        <EmptyState
          title={t(m.libraryEmptyTitle)}
          description={t(m.libraryEmptyDescription)}
          action={
            <Button
              variant="contained"
              startIcon={<LibraryAddOutlinedIcon />}
              onClick={() => void pickAndImport()}
            >
              {t(m.libraryImportBoardFiles)}
            </Button>
          }
        />
      </Box>
    );
  }

  return (
    <>
      <List sx={{ mb: 2, px: 1 }}>
        <ListItem disablePadding>
          <ListItemButton onClick={() => void pickAndImport()}>
            <ListItemIcon>
              <LibraryAddOutlinedIcon />
            </ListItemIcon>
            <ListItemText primary={t(m.libraryImportBoardFiles)} />
          </ListItemButton>
        </ListItem>
      </List>

      <BoardSetList
        boardSets={boardSets}
        activeBoardSetId={activeBoardSetId}
        onNavigate={onNavigate}
        onRequestDelete={setDeleteTarget}
        onShowDetails={setDetailsTarget}
      />

      <BoardSetDetailsDialog
        boardSet={detailsTarget}
        onClose={() => setDetailsTarget(null)}
      />

      <BoardSetDeleteDialog
        boardSet={deleteTarget}
        onDelete={() => void handleDelete()}
        onClose={() => setDeleteTarget(null)}
      />
    </>
  );
}
